async function loadNearbyPhoto(lat,lon,host){if(!host)return;host.innerHTML='<span class="photo-loading">📷 Buscando foto cercana…</span>';const api='https://commons.wikimedia.org/w/api.php?origin=*&format=json&action=query&generator=geosearch&ggsnamespace=6&ggsradius=1200&ggslimit=6&ggscoord='+encodeURIComponent(lat+'|'+lon)+'&prop=imageinfo&iiprop=url&iiurlwidth=360';try{const r=await fetch(api,{cache:'force-cache'});if(!r.ok)throw 0;const j=await r.json(),pages=Object.values(j?.query?.pages||{}),page=pages.find(x=>x?.imageinfo?.[0]?.thumburl);if(!page)throw 0;const ii=page.imageinfo[0],href=ii.descriptionurl||('https://commons.wikimedia.org/wiki/'+encodeURIComponent(page.title.replace(/ /g,'_')));host.innerHTML=`<a class="route-photo-link" href="${href}" target="_blank" rel="noopener"><img src="${ii.thumburl}" alt="Foto cercana a este punto del Camino"><span>📷 Foto cercana · Wikimedia Commons</span></a>`;}catch{host.innerHTML=`<a class="photo-nearby-link" href="${commonsNearbyUrl(lat,lon)}" target="_blank" rel="noopener">📷 Buscar fotos cercanas</a>`;}}

